// Street furniture, signs, markings and parked cars (generated by tools/streets.py), the crossings and
// traffic lights (the map's `cx`), what stands across paths (`pb`: gates, stiles, kissing gates, cycle
// barriers, cattle grids) and the treads and handrails of steps. Each kind is one instanced mesh built
// from a few coloured parts; signs and bus stop name plates carry their own text textures. Nothing here
// goes over the network: every player draws the same map.
import * as THREE from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { GLASS, glossy } from "./gloss";
import { CAR_SHAPES, carShape, GOLF, GOLF_PAINT, isCoachMake, LAND_ROVER, LR_PAINT, parkedMake, XR3I, XR3I_PAINT } from "./makes";
import { GameMap } from "./map";
import { Culler } from "./cull";
import { LAMPS_FAR } from "./view";

export type Part = [THREE.BufferGeometry, string, number, number, number, number?];   // geometry, colour, x, y, z, rotate about x

/** Merge parts into one geometry with per-vertex colours. Local axes: +x along the street, +z toward it. */
export function model(parts: Part[]): THREE.BufferGeometry {
  const geos = parts.map(([g, col, x, y, z, rx]) => {
    const c = g.index ? g.clone().toNonIndexed() : g.clone();
    if (rx) c.rotateX(rx);
    c.translate(x, y, z);
    const k = new THREE.Color(col);
    const n = c.attributes.position.count;
    c.setAttribute("color", new THREE.Float32BufferAttribute(new Array(n).fill(0).flatMap(() => [k.r, k.g, k.b]), 3));
    c.deleteAttribute("uv");
    return c;
  });
  return mergeGeometries(geos)!;
}
/** The street lamps' glass, shared by every lamp in Bath: world.ts lights it up after dark. */
export const LAMP_GLASS = new THREE.MeshBasicMaterial({ color: "#d8d4c2" });

/**
 * After dark, each lamp also shines as a soft glow that can be seen from right across town, long
 * after the lamp itself is too small to draw: one point per lamp, faded in from a few dozen metres
 * off (nearer, the glass and the light on the street do the work) and out only at the camera's
 * far edge, so lit streets twinkle through the night haze. world.ts sets how dark it is and
 * where that edge is.
 */
export const LAMP_GLOW = new THREE.ShaderMaterial({
  transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false,
  uniforms: { night: { value: 0 }, far: { value: 880 }, scale: { value: 380 } },   // scale: about half the drawn height over tan(half the field of view)
  vertexShader: `uniform float far, scale; varying float vFade;
    void main(){
      vec4 mv = modelViewMatrix * vec4(position, 1.0);
      float d = -mv.z;
      vFade = smoothstep(25.0, 60.0, d) * (1.0 - smoothstep(far * 0.8, far * 1.1, d));
      gl_PointSize = clamp(scale * 2.2 / d, 2.0, 14.0);
      gl_Position = projectionMatrix * mv;
    }`,
  fragmentShader: `uniform float night; varying float vFade;
    void main(){
      float r = length(gl_PointCoord - 0.5) * 2.0;
      float a = (1.0 - smoothstep(0.0, 1.0, r)) * night * vFade;
      if (a < 0.01) discard;
      gl_FragColor = vec4(vec3(1.0, 0.8, 0.5) * a, a);
    }`,
});

const box = (w: number, h: number, d: number) => new THREE.BoxGeometry(w, h, d);
const cyl = (r: number, h: number, seg = 8) => new THREE.CylinderGeometry(r, r, h, seg);
/** A box turned about the vertical by a (radians), for parts that don't run along x or z. */
const turned = (w: number, h: number, d: number, a: number) => box(w, h, d).rotateY(a);
/** A bar from a to b (scene metres), t thick. */
const beam = (a: THREE.Vector3, b: THREE.Vector3, t: number) => {
  const g = box(t, t, a.distanceTo(b) || 0.01);
  const m = new THREE.Matrix4().lookAt(a, b, Math.abs(b.y - a.y) > 0.99 * a.distanceTo(b) ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 1, 0));
  return g.applyMatrix4(m).translate((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2);
};
