/** The one Golf Driver's shape (golfdriver.ts): not a make's, so never among the parked cars. */
export const GOLF_DRIVER_SHAPE = CAR_SHAPES;

/** The everyday car's parts in one of its shapes (makes.ts): the body and its bits, then its four wheels. White parts take its paint. */
function carParts(shape = 0): Part[] {
  if (shape === 3) return landRoverParts();
  if (shape === 4) return golfParts();
  if (shape === GOLF_DRIVER_SHAPE) return golfParts(true);
  if (shape === 5) return xr3iParts();
  const S = SHAPES[shape] ?? SHAPES[0], [lx, ly, lz, lw] = S.lamp, [tx, ty, tz, th] = S.tail, f = S.body[2][0], b = S.body[6][0];
  const box = (w: number, h: number, d: number) => new THREE.BoxGeometry(w, h, d);
  return [
    [prof(S.body, S.W), "#ffffff", 0, 0, 0], [prof([...S.cab, [S.cab[3][0], S.cab[0][1]]], S.cabW), "#ffffff", 0, 0, 0],
    [prof(glass(S.cab), S.cabW + 0.04), GLASS, 0, 0, 0], ...pillars(S.cab, S.cabW, "#ffffff", S.b, S.c),
    [box(0.06, 0.12, lw), "#f1f0e6", lx, ly, lz], [box(0.06, 0.12, lw), "#f1f0e6", lx, ly, -lz],   // headlights
    [box(0.04, 0.09, 0.62), "#202224", lx + 0.02, ly - 0.16, 0],                                  // the grille
    [box(0.06, th, 0.3), "#a3221b", tx, ty, tz], [box(0.06, th, 0.3), "#a3221b", tx, ty, -tz],   // tail lights
    [box(f - b, 0.12, S.W + 0.02), "#2b2d30", (f + b) / 2, 0.36, 0],                              // sills and the bumpers' undersides
    [box(0.03, 0.11, 0.5), "#f2f2ea", f + 0.01, 0.42, 0], [box(0.03, 0.11, 0.5), "#e8c42a", b - 0.01, 0.55, 0],   // plates
    ...[-S.axle, S.axle].flatMap((x) => [-S.track, S.track].flatMap((z) => [
      [new THREE.CylinderGeometry(S.r, S.r, 0.22, 12), "#18191b", x, S.r, z, Math.PI / 2] as Part,
      [new THREE.CylinderGeometry(S.r * 0.62, S.r * 0.62, 0.23, 10), "#9fa4a9", x, S.r, z, Math.PI / 2] as Part,
    ])),
  ];
}

/** A wheel that turns: its geometry about its own centre, and where that centre sits on the vehicle. */
export interface Wheel { geo: THREE.BufferGeometry; x: number; y: number; z: number }
/**
 * A vehicle's parts split into what's fixed and the front wheels, which are built about their own
 * centres so they can be turned with the steering (vehicles.ts, traffic.ts). A wheel is any part
 * lying on its side (a cylinder turned a quarter about x); the front ones are those ahead of the
 * middle. Parts sharing a wheel's spot (its hub) turn with it.
 */
export function steerable(parts: Part[]): { fixed: Part[]; wheels: Wheel[] } {
  const isWheel = (p: Part) => p[0] instanceof THREE.CylinderGeometry && p[5] === Math.PI / 2 && p[2] > 0.3;
  const fixed = parts.filter((p) => !isWheel(p)), spots = new Map<string, Part[]>();
  for (const p of parts.filter(isWheel)) {
    const k = `${p[2].toFixed(2)},${p[4].toFixed(2)}`;
    (spots.get(k) ?? spots.set(k, []).get(k)!).push(p);
  }
  const wheels: Wheel[] = [];
  for (const group of spots.values()) {
    const [, , x, y, z] = group[0];
    wheels.push({ geo: model(group.map((p) => [p[0], p[1], p[2] - x, p[3] - y, p[4] - z, p[5]] as Part)), x, y, z });
  }
  return { fixed, wheels };
}

const carSteer: { body: THREE.BufferGeometry; wheels: Wheel[] }[] = [];
/** The everyday car for driving, in a shape (carShape): its body without the front wheels, and those on their own to turn with the steering. */
export function carSteerable(shape = 0): { body: THREE.BufferGeometry; wheels: Wheel[] } {
  if (!carSteer[shape]) { const { fixed, wheels } = steerable(carParts(shape)); carSteer[shape] = { body: model(fixed), wheels }; }
  return carSteer[shape];
}

/**
 * The everyday cars' paint, mostly what's on a British street (silver, white, black, grey, blue, red),
 * and every fifth a bright one: a proper red, a bright blue, yellow, orange, teal or a metallic green.
 */
export const CAR_PAINT = [
  "#c4c8cc", "#f0f1ef", "#16181c", "#4c535b", "#d3221b",
  "#1c3b78", "#b4b9be", "#8c1b20", "#eceeec", "#1f66c8",
  "#5f666e", "#121417", "#d0d3d5", "#2a5c99", "#efb81a",
  "#f5f5f1", "#1e4a33", "#3b4048", "#b8231e", "#e5631a",
  "#c8b68c", "#22324f", "#a9aeb3", "#1b1d22", "#14898a",
  "#e6e8e6", "#8e949a", "#7a1a2a", "#2b5d6a", "#2f8a4c",
];
/** A car's paint by number, in its make's colours (makes.ts). The everyday ones mix their make in, so a street's ten numbers reach the whole range. */
export const paintFor = (make: number, n: number) => {
  if (isCoachMake(make)) return "#ffffff";
  const p = make === LAND_ROVER ? LR_PAINT : make === GOLF ? GOLF_PAINT : make === XR3I ? XR3I_PAINT : null;
  return p ? p[n % p.length] : CAR_PAINT[(n + 7 * make) % CAR_PAINT.length];
};

const carGeo: THREE.BufferGeometry[] = [];
/** The everyday parked car in a shape (carShape), white where it takes its paint. */
export function carGeometry(shape = 0): THREE.BufferGeometry { return (carGeo[shape] ??= model(carParts(shape))); }
/** The parked cars' own material, glossy so they show up in the shade (gloss.ts). */
let carMat: THREE.MeshLambertMaterial | null = null;

/** White plate with black lettering, like a modern Bath street sign. */
function plateTexture(text: string, w: number, h: number, sub?: string): THREE.CanvasTexture {
  const c = document.createElement("canvas");
  c.width = w; c.height = h;
  const g = c.getContext("2d")!;
  g.fillStyle = "#f7f6f1"; g.fillRect(0, 0, w, h);
  g.strokeStyle = "#151515"; g.lineWidth = h * 0.06; g.strokeRect(h * 0.08, h * 0.08, w - h * 0.16, h - h * 0.16);
  g.fillStyle = "#151515";
  g.textAlign = "center"; g.textBaseline = "middle";
  let size = h * (sub ? 0.38 : 0.52);
  g.font = `600 ${size}px "Transport", "Helvetica Neue", Arial, sans-serif`;
  while (g.measureText(text).width > w * 0.88 && size > 8) { size -= 2; g.font = `600 ${size}px "Helvetica Neue", Arial, sans-serif`; }
  g.fillText(text, w / 2, sub ? h * 0.4 : h * 0.53);
  if (sub) { g.font = `500 ${h * 0.2}px "Helvetica Neue", Arial, sans-serif`; g.fillText(sub, w / 2, h * 0.75); }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

// A plate is painted only when someone comes near enough to see it, and one painting serves every
// sign with that name in every square; one nobody has been near for a while is let go. A town
// square has dozens of names, and painting them all up front was a good part of its memory.
const painted = new Map<string, { tex: THREE.CanvasTexture; used: number; mats: Set<THREE.MeshLambertMaterial> }>();
let blank: THREE.CanvasTexture | null = null;
let sweptAt = 0;
const PLATE_IDLE = 20000;

function blankPlate(): THREE.CanvasTexture {
  if (blank) return blank;
  const c = document.createElement("canvas");
  c.width = c.height = 4;
  const g = c.getContext("2d")!;
  g.fillStyle = "#f7f6f1"; g.fillRect(0, 0, 4, 4);
  blank = new THREE.CanvasTexture(c);
  blank.colorSpace = THREE.SRGBColorSpace;
  blank.userData.lent = true;
  return blank;
}

function showPlate(mat: THREE.MeshLambertMaterial, text: string, sub?: string) {
  const now = performance.now(), key = text + "|" + (sub ?? "");
  let e = painted.get(key);
  if (!e) {
    const tex = plateTexture(text, sub ? 384 : 512, sub ? 128 : 96, sub);
    tex.userData.lent = true;
    painted.set(key, (e = { tex, used: now, mats: new Set() }));
  }
  e.used = now;
  if (mat.map !== e.tex) { mat.map = e.tex; e.mats.add(mat); }
  if (now - sweptAt < 5000) return;
  sweptAt = now;
  for (const [k, p] of painted) if (now - p.used > PLATE_IDLE) {
    for (const m of p.mats) if (m.map === p.tex) m.map = blankPlate();
    p.tex.dispose();
    painted.delete(k);
  }
}

// (one function for every sign, reading what it says from the sign itself: a closure made while
// building a square would hold on to the whole square after it's gone)
function plateShown(this: THREE.Object3D, _r: THREE.WebGLRenderer, _s: THREE.Scene, _c: THREE.Camera, _g: THREE.BufferGeometry, mat: THREE.Material) {
  const [text, sub] = this.userData.plate as [string, string | undefined];
  if (mat instanceof THREE.MeshLambertMaterial && mat.userData.plate) showPlate(mat, text, sub);
}

/** Furniture baked into one model a cell (bake below): the parts' colours are kept as the bytes they
 *  were written in, and made linear here as three.js does them, a quarter of the memory of floats. */
const BAKED = new THREE.MeshLambertMaterial({ vertexColors: true });
BAKED.onBeforeCompile = (sh) => {
  sh.vertexShader = sh.vertexShader.replace("#include <color_vertex>", `#include <color_vertex>
    vColor.rgb = mix(pow(vColor.rgb * 0.9478672986 + vec3(0.0521327014), vec3(2.4)), vColor.rgb * 0.0773993808, vec3(lessThanEqual(vColor.rgb, vec3(0.04045))));`);
};
BAKED.customProgramCacheKey = () => "bakedFurniture";

const toSRGB = (c: number) => (c < 0.0031308 ? c * 12.92 : 1.055 * c ** 0.41666 - 0.055);
const toLinear = (c: number) => (c < 0.04045 ? c * 0.0773993808 : (c * 0.9478672986 + 0.0521327014) ** 2.4);

/** One model of many copies of models (each placed by its matrix), as world.ts's Geo holds them:
 *  normals in a byte each; colours (if the material takes them) in bytes, or floats where a colour
 *  isn't one the bytes can hold exactly (the flag returned says which). */
function* bake(parts: [THREE.BufferGeometry, THREE.Matrix4][], colours: boolean): Generator<void, [THREE.BufferGeometry, boolean]> {
  const n = parts.reduce((a, [g]) => a + g.attributes.position.count, 0);
  const P = new Float32Array(n * 3), N = new Int8Array(n * 3), C8 = colours ? new Uint8Array(n * 3) : null;
  let C32: Float32Array | null = null;
  const v = new THREE.Vector3(), nm = new THREE.Matrix3(), col = new THREE.Color();
  let at = 0;
  for (const [g, m] of parts) {
    if (at % 20000 > (at + g.attributes.position.count) % 20000) yield;
    const p = g.attributes.position, no = g.attributes.normal, c = g.attributes.color;
    nm.getNormalMatrix(m);
    for (let i = 0; i < p.count; i++, at++) {
      v.fromBufferAttribute(p, i).applyMatrix4(m);
      P[at * 3] = v.x; P[at * 3 + 1] = v.y; P[at * 3 + 2] = v.z;
      v.fromBufferAttribute(no, i).applyMatrix3(nm).normalize();
      N[at * 3] = Math.round(v.x * 127); N[at * 3 + 1] = Math.round(v.y * 127); N[at * 3 + 2] = Math.round(v.z * 127);
      if (!colours) continue;
      col.fromBufferAttribute(c as THREE.BufferAttribute, i);
      if (C32) { col.toArray(C32, at * 3); continue; }
      const s = [col.r, col.g, col.b].map((x) => toSRGB(x) * 255);
      if (s.some((x) => Math.abs(x - Math.round(x)) > 1e-3)) {
        C32 = new Float32Array(n * 3);
        for (let k = 0; k < at; k++) for (let j = 0; j < 3; j++) C32[k * 3 + j] = toLinear(C8![k * 3 + j] / 255);
        col.toArray(C32, at * 3);
        continue;
      }
      C8![at * 3] = Math.round(s[0]); C8![at * 3 + 1] = Math.round(s[1]); C8![at * 3 + 2] = Math.round(s[2]);
    }
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute("position", new THREE.BufferAttribute(P, 3));
  out.setAttribute("normal", new THREE.BufferAttribute(N, 3, true));
  if (C32) out.setAttribute("color", new THREE.BufferAttribute(C32, 3));
  else if (C8) out.setAttribute("color", new THREE.BufferAttribute(C8, 3, true));
  out.computeBoundingSphere();
  return [out, !!C32];
}

/** Street furniture, wires, bus stops, street name signs and road markings, built a kind at a time (yields between). */
export function* buildFurniture(map: GameMap, scene: THREE.Object3D, culler: Culler): Generator<void> {
  const D = map.d, Z0 = map.z0;
  const byKind = new Map<string, (string | number)[][]>();
  for (const f of D.fx ?? []) {
    const k = f[0] as string;
    (byKind.get(k) ?? byKind.set(k, []).get(k)!).push(f);
  }
  const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), up = new THREE.Vector3(0, 1, 0), one = new THREE.Vector3(1, 1, 1), p = new THREE.Vector3();
  const sc = new THREE.Vector3();
  const place = (f: (string | number)[], scale?: (f: (string | number)[]) => number[]) => {
    q.setFromAxisAngle(up, f[4] as number);
    return m4.compose(p.set(f[1] as number, (f[3] as number) - Z0, -(f[2] as number)), q, scale ? sc.fromArray(scale(f)) : one);
  };
  // What never changes once it's put up is baked, each 250 m square of it into one model a
  // material and distance it's drawn to, so a street's bins, bollards, benches and posts are one
  // draw instead of one a kind. Parked cars (which can be driven off), wheelie bins (each tinted),
  // and see-through or lit-up parts stay instanced.
  const baked = new Map<string, { material: THREE.Material; range: number; parts: [THREE.BufferGeometry, THREE.Matrix4][] }>();
  // one instanced mesh per 250 m square, so distant squares can be skipped
  const instanced = function* (geo: THREE.BufferGeometry, all: (string | number)[][], material: THREE.Material = mat, colour?: (f: (string | number)[]) => string,
    placed?: (f: (string | number)[], m: THREE.InstancedMesh, i: number) => void, range = 200, scale?: (f: (string | number)[]) => number[]): Generator<void> {
    const groups = new Map<string, (string | number)[][]>();
    if (!colour && !placed && (material === mat || material === LAMP_GLASS)) {
      for (let gi = 0; gi < all.length; gi++) {
        const f = all[gi];
        const k = `${Math.floor((f[1] as number) / 250)},${Math.floor((f[2] as number) / 250)}|${material.uuid}|${range}`;
        const b = baked.get(k) ?? baked.set(k, { material, range, parts: [] }).get(k)!;
        b.parts.push([geo, place(f, scale).clone()]);
        if (gi % 300 === 299) yield;
      }
      return;
    }
    for (let gi = 0; gi < all.length; gi++) {
      const f = all[gi];
      const k = `${Math.floor((f[1] as number) / 250)},${Math.floor((f[2] as number) / 250)}`;
      (groups.get(k) ?? groups.set(k, []).get(k)!).push(f);
      if (gi % 300 === 299) yield;
    }
    for (const items of groups.values()) {
      const m = new THREE.InstancedMesh(geo, material, items.length);
      for (let i = 0; i < items.length; i++) {
        const f = items[i];
        m.setMatrixAt(i, place(f, scale)); if (colour) m.setColorAt(i, new THREE.Color(colour(f))); placed?.(f, m, i);
        if (i % 300 === 299) yield;
      }
      m.castShadow = true; m.receiveShadow = true;
      m.computeBoundingSphere();
      scene.add(m);
      culler.add(m, range);
      yield;
    }
  };
  for (const kind of ["bin", "bollard", "bench", "info", "phone"]) yield* instanced(MODELS[kind](), byKind.get(kind) ?? []);
  // post boxes as the map says they stand: a pillar box, one in a wall, one on a post
  const boxes = byKind.get("postbox") ?? [];
  yield* instanced(MODELS.postbox(), boxes.filter((f) => !f[5]));
  yield* instanced(MODELS.postboxWall(), boxes.filter((f) => f[5] === 1));
  yield* instanced(MODELS.postboxLamp(), boxes.filter((f) => f[5] === 2));
  const lamps = byKind.get("lamp") ?? [];
  yield* instanced(MODELS.lamp(), lamps, mat, undefined, undefined, LAMPS_FAR);
  yield* instanced(MODELS.lampGlass(), lamps, LAMP_GLASS, undefined, undefined, LAMPS_FAR);
  // every lamp's glow, under its glass (LAMP_GLOW)
  if (lamps.length) {
    const pos = new Float32Array(lamps.length * 3);
    lamps.forEach((f, i) => {
      const a = f[4] as number;
      pos.set([(f[1] as number) + 1.2 * Math.sin(a), (f[3] as number) - Z0 + 6.1, -(f[2] as number) + 1.2 * Math.cos(a)], i * 3);
    });
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    g.computeBoundingSphere();
    const glow = new THREE.Points(g, LAMP_GLOW);
    glow.renderOrder = 4;
    scene.add(glow);
  }
  // a parked car someone gets in becomes a vehicle (vehicles.ts): squash its furniture away
  const cars = new Map<(string | number)[], [THREE.InstancedMesh, number]>();
  // each in its make's shape and colours (makes.ts), as vehicles.ts names it
  const parked = byKind.get("car") ?? [], make = new Map(parked.map((f, k) => [f, parkedMake(map, f[1] as number, f[2] as number, k)]));
  carMat ??= glossy(new THREE.MeshLambertMaterial({ vertexColors: true }));
  for (let shape = 0; shape < CAR_SHAPES; shape++)
    yield* instanced(carGeometry(shape), parked.filter((f) => carShape(make.get(f)!) === shape), carMat, (f) => paintFor(make.get(f)!, f[5] as number), (f, m, i) => cars.set(f, [m, i]));
  map.onTakeCar = (f) => {
    const c = cars.get(f);
    if (!c) return;
    c[0].setMatrixAt(c[1], new THREE.Matrix4().makeScale(0, 0, 0));
    c[0].instanceMatrix.needsUpdate = true;
  };
  // (any already driven off before this square of Bath was built)
  for (const s of map.spare) if (s.taken) map.onTakeCar(s.f);
  yield;
  yield* instanced(MODELS.pole(), byKind.get("pole") ?? []);
  // overhead wires, sagging a little between their ends
  const wpos: number[] = [];
  for (const [x0, y0, z0, x1, y1, z1] of D.wr ?? []) {
    const n = 6, len = Math.hypot(x1 - x0, y1 - y0), sag = Math.min(0.9, len * 0.018);
    for (let k = 0; k < n; k++) {
      const a = k / n, b = (k + 1) / n;
      const P = (t: number) => [x0 + (x1 - x0) * t, z0 + (z1 - z0) * t - Z0 - sag * 4 * t * (1 - t), -(y0 + (y1 - y0) * t)];
      wpos.push(...P(a), ...P(b));
    }
  }
  if (wpos.length) {
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(wpos, 3));
    scene.add(new THREE.LineSegments(g, new THREE.LineBasicMaterial({ color: "#1d1f21", transparent: true, opacity: 0.75 })));
  }
  // wheelie bins: black (general waste), green (garden), blue (recycling)
  yield* instanced(MODELS.wheelie(), byKind.get("wheelie") ?? [], mat, (f) => ["#2a2c2e", "#2f5e35", "#2d4f86"][(f[5] as number) % 3]);

  // bus stops: flag, optional shelter, and a name plate
  yield;
  const stops = byKind.get("bus") ?? [];
  yield* instanced(MODELS.busflag(), stops);
  const sheltered = stops.filter((f) => f[6]);
  yield* instanced(MODELS.shelter(), sheltered);
  yield* instanced(MODELS.shelterglass(), sheltered, new THREE.MeshLambertMaterial({ vertexColors: true, transparent: true, opacity: 0.28, depthWrite: false }));
  const plates = new Map<string, THREE.MeshLambertMaterial>();
  const plateFor = (text: string, sub?: string) => {
    const key = text + "|" + (sub ?? "");
    let m = plates.get(key);
    if (!m) { plates.set(key, (m = new THREE.MeshLambertMaterial({ map: blankPlate() }))); m.userData.plate = true; }
    return m;
  };
  const shows = (mesh: THREE.Mesh, text: string, sub?: string) => { mesh.userData.plate = [text, sub]; mesh.onBeforeRender = plateShown; };
  const edge = new THREE.MeshLambertMaterial({ color: "#151515" });
  for (const [k, f] of stops.entries()) {
    if (k % 16 === 15) yield;
    const plate = plateFor(f[5] as string, "Bus stop");
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.3, 0.04), [edge, edge, edge, edge, plate, plate]);
    shows(mesh, f[5] as string, "Bus stop");
    mesh.applyMatrix4(place(f));
    mesh.position.y += 2.1;
    scene.add(mesh);
    culler.add(mesh, 120);
  }

  // street name signs
  yield;
  const signs = byKind.get("sign") ?? [];
  yield* instanced(MODELS.signposts(), signs);
  for (const [k, f] of signs.entries()) {
    if (k % 16 === 15) yield;
    const plate = plateFor(f[5] as string);
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.3, 0.035), [edge, edge, edge, edge, plate, plate]);
    shows(mesh, f[5] as string);
    mesh.applyMatrix4(place(f));
    mesh.position.y += 1.2;
    mesh.castShadow = true;
    scene.add(mesh);
    culler.add(mesh, 120);
  }

  // road markings: thin white strips just above the carriageway
  const pos: number[] = [];
  yield;
  // crossings and traffic lights (cx): a zebra's stripes and its beacons, a light-controlled
  // crossing's studs and stop lines and its lights at each kerb, facing the traffic that stops there
  // (we drive on the left), and the lights at a junction
  const quad = (x: number, y: number, z: number, a: number, s0: number, s1: number, t0: number, t1: number) => {
    const ux = Math.cos(a), uy = Math.sin(a), nx = -uy, ny = ux;
    const P = (s: number, t: number) => [x + ux * s + nx * t, z, -(y + uy * s + ny * t)];
    const A = P(s0, t0), B = P(s1, t0), C = P(s1, t1), Dd = P(s0, t1);
    pos.push(...A, ...C, ...B, ...A, ...Dd, ...C);
  };
  const beacons: (string | number)[][] = [], lights: (string | number)[][] = [];
  for (const c of D.cx ?? []) {
    const [x, y, z, a, kind, w] = c as [number, number, number, number, string, number];
    const h = w / 2, g = z - Z0 + 0.085, off = h + 0.5, nx = -Math.sin(a), ny = Math.cos(a);
    if (kind === "z") for (let t = -h + 0.25; t + 0.5 <= h - 0.15; t += 1.0) quad(x, y, g, a, -1.3, 1.3, t, t + 0.5);
    if (kind === "p") for (const s of [-1.3, 1.3]) for (let t = -h + 0.2; t + 0.12 <= h - 0.2; t += 0.5) quad(x, y, g, a, s - 0.06, s + 0.06, t, t + 0.12);
    // stop lines: on the left half for traffic going along the street's points, the right for the rest
    if (kind !== "z") { const s = kind === "p" ? 3 : 2; quad(x, y, g, a, -s - 0.15, -s + 0.15, 0, h - 0.2); quad(x, y, g, a, s - 0.15, s + 0.15, -h + 0.2, 0); }
    const pole = z + 0.17;
    if (kind === "z") for (const k of [1, -1]) beacons.push(["beacon", x + nx * off * k, y + ny * off * k, pole, 0]);
    else {
      // the left kerb's lights face back down the street at the traffic coming along it, the right's the other way
      lights.push(["signal", x + nx * off, y + ny * off, pole, a - Math.PI / 2]);
      lights.push(["signal", x - nx * off, y - ny * off, pole, a + Math.PI / 2]);
    }
  }
  // level crossings (lx): the deck across the line, flush with the rails' feet and sloping down to
  // the way either side, and the lights on each side of the line beside the way
  const deck: number[] = [], xlights: (string | number)[][] = [], xcross: (string | number)[][] = [];
  for (const c of D.lx ?? []) {
    const [x, y, z, a, kind, w, half] = c as [number, number, number, number, string, number, number];
    const ux = Math.cos(a), uy = Math.sin(a), nx = -uy, ny = ux, top = z - Z0 + DECK_TOP, s = w / 2;
    const P = (u: number, t: number, h: number) => [x + ux * u + nx * t, h, -(y + uy * u + ny * t)];
    const strip = (t0: number, t1: number, h0: number, h1: number) => deck.push(...P(-s, t0, h0), ...P(s, t1, h1), ...P(s, t0, h0), ...P(-s, t0, h0), ...P(-s, t1, h1), ...P(s, t1, h1));
    strip(-half, half, top, top);
    strip(half, half + DECK_RAMP, top, z - Z0);
    strip(-half - DECK_RAMP, -half, z - Z0, top);
    for (const side of [1, -1]) {
      const f = ["xlights", x + ux * (s + 0.6) * side + nx * (half + 1.3) * side, y + uy * (s + 0.6) * side + ny * (half + 1.3) * side, z, side > 0 ? a + Math.PI : a];
      xlights.push(f);
      if (kind === "r") xcross.push(f);
    }
  }
  if (deck.length) {
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(deck, 3));
    g.computeVertexNormals();
    const m = new THREE.Mesh(g, new THREE.MeshLambertMaterial({ color: "#4f4d49", side: THREE.DoubleSide }));
    m.receiveShadow = true;
    scene.add(m);
  }
  yield* instanced(MODELS.xlights(), xlights);
  yield* instanced(MODELS.xcross(), xcross);
  yield* instanced(MODELS.beacon(), beacons);
  yield* instanced(MODELS.beaconGlobe(), beacons, S_BEACON);
  yield* instanced(MODELS.signal(), lights);
  // gates, stiles and the rest across paths and roads (pb), each stretched to the gap or the way it stands in
  const across = new Map<string, (string | number)[][]>();
  for (const f of D.pb ?? []) (across.get(f[0] as string) ?? across.set(f[0] as string, []).get(f[0] as string)!).push(f);
  const wide = (f: (string | number)[]) => Math.max(0.8, f[5] as number);
  yield* instanced(MODELS.gate(), across.get("gate") ?? [], mat, undefined, undefined, 200, (f) => [wide(f), 1, wide(f)]);
  yield* instanced(MODELS.stile(), across.get("stile") ?? [], mat, undefined, undefined, 200, (f) => [wide(f), 1, 1]);
  yield* instanced(MODELS.kiss(), across.get("kiss") ?? [], mat, undefined, undefined, 200, (f) => [wide(f), 1, 1]);
  yield* instanced(MODELS.cycle(), across.get("cycle") ?? [], mat, undefined, undefined, 200, (f) => [1, 1, wide(f)]);
  yield* instanced(MODELS.lift(), across.get("lift") ?? [], mat, undefined, undefined, 200, (f) => [1, 1, wide(f)]);
  yield* instanced(MODELS.grid(), across.get("grid") ?? [], mat, undefined, undefined, 200, (f) => [1, 1, wide(f)]);
  yield* instanced(MODELS.block(), across.get("block") ?? []);
  for (const b of baked.values()) {
    const [g, floats] = yield* bake(b.parts, b.material === mat);
    const m = new THREE.Mesh(g, b.material === mat ? (floats ? mat : BAKED) : b.material);
    m.castShadow = true; m.receiveShadow = true;
    scene.add(m);
    culler.add(m, b.range);
    yield;
  }
  baked.clear();
  yield* stepsDetail(map, scene, culler, mat);
  let mk = 0;
  for (const [ax, ay, bx, by, za, zb, kind] of D.mk ?? []) {
    const dx = bx - ax, dy = by - ay, l = Math.hypot(dx, dy) || 1;
    const w = (kind ? 0.15 : 0.1) / 2, nx = -dy / l * w, ny = dx / l * w;
    const ya = map.ground(ax, -ay) + 0.085, yb = map.ground(bx, -by) + 0.085;
    void za; void zb;
    const A = [ax + nx, ya, -(ay + ny)], B = [bx + nx, yb, -(by + ny)], C = [bx - nx, yb, -(by - ny)], Dd = [ax - nx, ya, -(ay - ny)];
    pos.push(...A, ...Dd, ...C, ...A, ...C, ...B);
    if (++mk % 400 === 399) yield;
  }
  if (pos.length) {
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
    g.computeVertexNormals();
    const m = new THREE.Mesh(g, new THREE.MeshLambertMaterial({ color: "#e9e7df", side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: -5, polygonOffsetUnits: -10 }));
    m.receiveShadow = true;
    scene.add(m);
  }
}

/** A level crossing's deck: just over the sleepers, so the rails show through it, and the ramp
 *  either side down to the way. */
const DECK_TOP = 0.34, DECK_RAMP = 1.0;

/** A Belisha beacon's globe: amber, and bright enough to read at dusk. */
const S_BEACON = new THREE.MeshBasicMaterial({ vertexColors: true, color: "#ffb02a" });

/** Steepest a flight climbs (rise per metre along it), about a stair's usual pitch. */
const STAIR_PITCH = 0.7;
/** How far a handrail stands above the treads. */
const RAIL_HEIGHT = 0.9;

/**
 * Steps where the map says how they're built: solid treads (as many as it says, else one for every
 * 16 cm of rise) with a dark nosing, and handrails on posts along the sides it names. The flight
 * climbs evenly between the ground at its two ends, but never dips into the ground on the way and
 * never rises steeper than a stair, so where it meets a retaining wall it starts climbing early to
 * reach the top rather than leaving its rails hanging off the wall. One merged mesh for the
 * square's steps.
 */
function* stepsDetail(map: GameMap, scene: THREE.Object3D, culler: Culler, mat: THREE.Material): Generator<void> {
  const parts: Part[] = [];
  const ground = (x: number, y: number) => map.ground(x, -y);
  const v3 = (x: number, y: number, h: number) => new THREE.Vector3(x, h, -y);
  let n = 0;
  for (const r of map.d.rd) {
    // a flight on a span is the bridge's to draw, with its parapets
    if (r.c !== "steps" || r.p.length < 2 || r.bridge) continue;
    if (++n % 20 === 0) yield;
    const lay = stairLayout(r, ground);
    if (!lay) continue;
    const { L, w, along, height } = lay;
    const treads = r.sc ?? (lay.rise > 0.3 ? Math.round(lay.rise / 0.16) : 0);
    const count = Math.min(treads, 240, Math.floor(L / 0.2));
    for (let k = 0; k < count; k++) {
      const s0 = L * k / count, s1 = L * (k + 1) / count, [x, y, ux, uy] = along((s0 + s1) / 2);
      const top = Math.max(height(s0), height(s1)), nx = -uy * w / 2, ny = ux * w / 2;
      const bottom = Math.min(ground(x, y), ground(x + nx, y + ny), ground(x - nx, y - ny), height(s0), height(s1)) - 0.15;
      const turn = Math.atan2(ux, -uy), depth = s1 - s0 + 0.02;
      parts.push([box(w * 0.95, top - bottom, depth).rotateY(turn), "#9b968b", x, (top + bottom) / 2, -y]);
      // the nosing, on the tread's leading edge whichever way the flight climbs
      const lead = height(s1) >= height(s0) ? s0 : s1, [ex, ey] = along(lead);
      parts.push([box(w * 0.95, 0.05, 0.06).rotateY(turn), "#3f3d38", ex, top, -ey]);
    }
    const sides = (r.hr ?? 0) & 7;
    for (const [bit, off] of [[1, w / 2 - 0.08], [2, -w / 2 + 0.08], [4, 0]] as const) {
      if (!(sides & bit)) continue;
      const posts = Math.max(2, Math.ceil(L / 1.5) + 1);
      let last: THREE.Vector3 | null = null;
      for (let k = 0; k < posts; k++) {
        const s = 0.15 + (L - 0.3) * k / (posts - 1), [x, y, ux, uy] = along(s), px = x - uy * off, py = y + ux * off;
        const foot = height(s);
        // no rail inside the flight where it turns back on itself, nor where a bank or wall
        // already stands higher than the rail beside the treads
        if (off && (lay.inside(px, py, Math.abs(off) - 0.25) || ground(px, py) > foot + 0.5)) { last = null; continue; }
        const top = v3(px, py, foot + RAIL_HEIGHT);
        parts.push([beam(v3(px, py, foot), top, 0.045), "#2b2e31", 0, 0, 0]);
        if (last) parts.push([beam(last, top, 0.05), "#2b2e31", 0, 0, 0]);
        last = top;
      }
    }
  }
  if (!parts.length) return;
  const m = new THREE.Mesh(model(parts), mat);
  m.castShadow = true; m.receiveShadow = true;
  scene.add(m);
  culler.add(m, 200);
}

/**
 * A flight's line and heights: `along(s)` the point and heading s metres along it, `height(s)` the
 * treads' level there, `inside(x, y, d)` whether a point is within d of the flight's own line.
 */
function stairLayout(r: { p: number[][]; w?: number }, ground: (x: number, y: number) => number) {
  const pts = r.p, len: number[] = [0];
  for (let k = 1; k < pts.length; k++) len.push(len[k - 1] + Math.hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]));
  const L = len[len.length - 1];
  if (L < 1) return null;
  const along = (s: number): [number, number, number, number] => {
    let k = 1;
    while (k < len.length - 1 && len[k] < s) k++;
    const f = (s - len[k - 1]) / ((len[k] - len[k - 1]) || 1), a = pts[k - 1], b = pts[k];
    const dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy) || 1;
    return [a[0] + dx * f, a[1] + dy * f, dx / l, dy / l];
  };
  const STEP = 0.25, N = Math.max(2, Math.ceil(L / STEP)), h: number[] = [];
  const g0 = ground(pts[0][0], pts[0][1]), g1 = ground(pts[pts.length - 1][0], pts[pts.length - 1][1]);
  for (let i = 0; i <= N; i++) {
    const s = L * i / N, [x, y] = along(s);
    h.push(Math.max(g0 + (g1 - g0) * s / L, ground(x, y)));
  }
  // no steeper than a stair either way: a sudden rise (a wall's top under the line) is climbed to
  // over the treads before it
  const most = STAIR_PITCH * L / N;
  for (let i = N - 1; i >= 0; i--) h[i] = Math.max(h[i], h[i + 1] - most);
  for (let i = 1; i <= N; i++) h[i] = Math.max(h[i], h[i - 1] - most);
  const height = (s: number) => {
    const f = Math.min(N, Math.max(0, s / L * N)), i = Math.min(N - 1, Math.floor(f));
    return h[i] + (h[i + 1] - h[i]) * (f - i);
  };
  const inside = (x: number, y: number, d: number) => {
    for (let k = 1; k < pts.length; k++) {
      const a = pts[k - 1], b = pts[k], dx = b[0] - a[0], dy = b[1] - a[1], l2 = dx * dx + dy * dy || 1;
      const t = Math.min(1, Math.max(0, ((x - a[0]) * dx + (y - a[1]) * dy) / l2));
      if (Math.hypot(a[0] + dx * t - x, a[1] + dy * t - y) < d) return true;
    }
    return false;
  };
  return { L, w: r.w ?? 1.8, along, height, inside, rise: Math.abs(g1 - g0) };
}

// ---- shop signs and landmarks -------------------------------------------------------------
const SIGN_STYLE: Record<string, { bg: string; fg: string; font: string }> = {
  pub: { bg: "#1f3b2d", fg: "#e2c477", font: "Georgia, 'Times New Roman', serif" },
  cafe: { bg: "#5d7461", fg: "#f3ead6", font: "Georgia, serif" },
  shop: { bg: "#1d2b45", fg: "#f4f1ea", font: "'Helvetica Neue', Arial, sans-serif" },
  agent: { bg: "#5a1f2b", fg: "#f4efe6", font: "Georgia, serif" },
  health: { bg: "#f5f5f2", fg: "#1b6e3a", font: "'Helvetica Neue', Arial, sans-serif" },
  civic: { bg: "#202326", fg: "#ece4cf", font: "Georgia, serif" },
};

/** Fascias are painted onto shared sheets, CELL_W x CELL_H pixels each, COLS across and ROWS down. */
const CELL_W = 384, CELL_H = 48, COLS = 4, ROWS = 32;

/** Painted timber fascia: lettering centred on a coloured board with a thin moulding, drawn into
 *  cell (cx, cy) of a sheet. aspect: the board's width over its height, so the lettering, squeezed
 *  into the cell, comes out in proportion once it's stretched across the board. */
function paintFascia(g: CanvasRenderingContext2D, cx: number, cy: number, text: string, style: string, aspect: number) {
  const st = SIGN_STYLE[style] ?? SIGN_STYLE.shop;
  const x0 = cx * CELL_W, y0 = cy * CELL_H, w = CELL_W, h = CELL_H;
  g.save();
  g.beginPath(); g.rect(x0, y0, w, h); g.clip();
  g.fillStyle = st.bg; g.fillRect(x0, y0, w, h);
  // the board is aspect : 1, the cell w : h; draw in board proportions, squeezed across
  const sx = (w / h) / aspect;
  g.translate(x0 + w / 2, y0); g.scale(sx, 1);
  const bw = w / sx;
  g.strokeStyle = st.fg; g.globalAlpha = 0.6; g.lineWidth = h * 0.04;
  g.strokeRect(-bw / 2 + h * 0.1, h * 0.1, bw - h * 0.2, h - h * 0.2);
  g.globalAlpha = 1;
  g.fillStyle = st.fg; g.textAlign = "center"; g.textBaseline = "middle";
  let size = h * 0.5;
  g.font = `600 ${size}px ${st.font}`;
  while (g.measureText(text).width > bw * 0.86 && size > 6) { size -= 1; g.font = `600 ${size}px ${st.font}`; }
  g.fillText(text, 0, h * 0.54);
  g.restore();
}

/** A pub's hanging board: the name on up to three lines, in the board's own proportions (BW x BH pixels per cell). */
const BW = 192, BH = 228, BCOLS = 4;
function paintBoard(g: CanvasRenderingContext2D, n: number, text: string) {
  const st = SIGN_STYLE.pub, x0 = (n % BCOLS) * BW, y0 = Math.floor(n / BCOLS) * BH;
  g.save();
  g.beginPath(); g.rect(x0, y0, BW, BH); g.clip();
  g.fillStyle = st.bg; g.fillRect(x0, y0, BW, BH);
  g.strokeStyle = st.fg; g.globalAlpha = 0.6; g.lineWidth = 5;
  g.strokeRect(x0 + 12, y0 + 12, BW - 24, BH - 24);
  g.globalAlpha = 1;
  g.fillStyle = st.fg; g.textAlign = "center"; g.textBaseline = "middle";
  // split into at most three lines of about equal length
  const words = text.split(/\s+/).filter(Boolean), lines: string[] = [];
  const per = Math.max(1, Math.ceil(words.length / Math.min(3, words.length)));
  for (let i = 0; i < words.length; i += per) lines.push(words.slice(i, i + per).join(" "));
  let size = 44;
  const fit = () => { g.font = `600 ${size}px ${st.font}`; return Math.max(...lines.map((l) => g.measureText(l).width)); };
  while (fit() > BW - 44 && size > 8) size -= 1;
  lines.forEach((l, i) => g.fillText(l, x0 + BW / 2, y0 + BH / 2 + (i - (lines.length - 1) / 2) * size * 1.15));
  g.restore();
}

/** Shop window: glazing bars over dark glass, with a stall riser below. */
let shopWindow: THREE.CanvasTexture | null = null;
const lend = (t: THREE.CanvasTexture) => { t.userData.lent = true; return t; };

/** Once a square's own painted sheet is up on the graphics card, the page's copy of the painting
 *  goes: the square is built afresh if it comes back, so it's never sent up again. */
function letGoOnceSent(t: THREE.CanvasTexture) {
  t.onUpdate = () => { const c = t.image as HTMLCanvasElement; c.width = c.height = 0; t.onUpdate = null; };
}

function shopWindowTexture(): THREE.CanvasTexture {
  const c = document.createElement("canvas");
  c.width = 256; c.height = 128;
  const g = c.getContext("2d")!;
  const glass = g.createLinearGradient(0, 0, 256, 128);
  glass.addColorStop(0, "#41505c"); glass.addColorStop(0.5, "#26333d"); glass.addColorStop(1, "#52646f");
  g.fillStyle = glass; g.fillRect(0, 0, 256, 104);
  g.fillStyle = "#e6e0d2";
  g.fillRect(0, 0, 256, 6); g.fillRect(0, 100, 256, 6); g.fillRect(0, 0, 6, 106); g.fillRect(250, 0, 6, 106);
  g.fillRect(84, 0, 4, 104); g.fillRect(168, 0, 4, 104); g.fillRect(0, 30, 256, 3);
  g.fillStyle = "#3b4044"; g.fillRect(0, 106, 256, 22);        // stall riser
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/**
 * Shopfronts: a painted fascia over a shop window (pubs get a hanging sign instead of the window).
 * The fascias of each patch of signs share one painted sheet, and each patch is merged into a few
 * meshes, so a busy high street costs a handful of draws. Built a few signs at a time (yields).
 */
export function* buildShops(map: GameMap, scene: THREE.Object3D, culler: Culler): Generator<void> {
  const D = map.d, Z0 = map.z0;
  const signs = (D.sh ?? []).filter((s) => !s[7]);   // (a pub that's a set piece hangs its own: landmarks/setpieces.ts)
  if (!signs.length) return;
  const shopWin = new THREE.MeshLambertMaterial({ map: (shopWindow ??= lend(shopWindowTexture())) });
  const dark = new THREE.MeshLambertMaterial({ color: "#2a2d30" });
  // neighbours together, so each sheet's signs stand close and its meshes can be skipped when far off
  const patch = (f: (string | number)[]) => Math.floor(+f[0] / 200) * 10007 + Math.floor(+f[1] / 200);
  signs.sort((a, b) => patch(a) - patch(b) || +a[0] - +b[0]);
  const PER = COLS * ROWS;
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), up = new THREE.Vector3(0, 1, 0), one = new THREE.Vector3(1, 1, 1), pos = new THREE.Vector3();
  for (let s0 = 0; s0 < signs.length; s0 += PER) {
    const batch = signs.slice(s0, s0 + PER), rows = Math.ceil(batch.length / COLS);
    const sheet = document.createElement("canvas");
    sheet.width = CELL_W * COLS; sheet.height = CELL_H * Math.max(1, rows);
    const g = sheet.getContext("2d")!;
    const faces: THREE.BufferGeometry[] = [], darks: THREE.BufferGeometry[] = [], wins: THREE.BufferGeometry[] = [], boards: THREE.BufferGeometry[] = [];
    const pubs = batch.filter((s) => s[6] === "pub").length, bsheet = document.createElement("canvas");
    bsheet.width = BW * BCOLS; bsheet.height = BH * Math.max(1, Math.ceil(pubs / BCOLS));
    const bg = bsheet.getContext("2d")!;
    let nb = 0;
    for (let k = 0; k < batch.length; k++) {
      const [x, y, z, ang, width, name, style] = batch[k];
      const w = width as number, cx = k % COLS, cy = Math.floor(k / COLS);
      paintFascia(g, cx, cy, name as string, style as string, w / 0.62);
      q.setFromAxisAngle(up, ang as number);
      m4.compose(pos.set(x as number, (z as number) - Z0, -(y as number)), q, one);
      // the fascia's painted face, its cell of the sheet (v runs up the sheet)
      const u0 = cx / COLS, u1 = (cx + 1) / COLS, v1 = 1 - cy / Math.max(1, rows), v0 = 1 - (cy + 1) / Math.max(1, rows);
      const face = (fw: number, at: THREE.Matrix4) => {
        const f = new THREE.PlaneGeometry(fw, 0.62).applyMatrix4(at);
        const uv = f.attributes.uv as THREE.BufferAttribute;
        for (let i = 0; i < uv.count; i++) uv.setXY(i, uv.getX(i) ? u1 : u0, uv.getY(i) ? v1 : v0);
        faces.push(f.applyMatrix4(m4));
      };
      face(w, new THREE.Matrix4().makeTranslation(0, 3.05, 0.142));
      darks.push(new THREE.BoxGeometry(w, 0.62, 0.14).translate(0, 3.05, 0.07).applyMatrix4(m4));
      if (style !== "pub") {
        const win = new THREE.PlaneGeometry(w - 0.5, 2.25).translate(0, 1.55, 0.061).applyMatrix4(m4);
        wins.push(win);
        darks.push(new THREE.BoxGeometry(w - 0.5, 2.25, 0.06).translate(0, 1.55, 0.03).applyMatrix4(m4));
      } else {
        // hanging sign on an iron bracket at one end of the fascia, painted both sides
        darks.push(new THREE.BoxGeometry(0.05, 0.05, 1.1).translate(w / 2 - 0.3, 3.75, 0.55).applyMatrix4(m4));
        darks.push(new THREE.BoxGeometry(0.06, 0.95, 0.8).translate(w / 2 - 0.3, 3.2, 0.7).applyMatrix4(m4));
        const bu0 = (nb % BCOLS) / BCOLS, bu1 = bu0 + 1 / BCOLS, brows = Math.max(1, Math.ceil(pubs / BCOLS)), br = Math.floor(nb / BCOLS);
        const bv1 = 1 - br / brows, bv0 = 1 - (br + 1) / brows;
        paintBoard(bg, nb++, name as string);
        for (const side of [1, -1]) {
          const at = new THREE.Matrix4().makeRotationY(side * Math.PI / 2).premultiply(new THREE.Matrix4().makeTranslation(w / 2 - 0.3 + side * 0.031, 3.2, 0.7));
          const f = new THREE.PlaneGeometry(0.8, 0.95).applyMatrix4(at);
          const uv = f.attributes.uv as THREE.BufferAttribute;
          for (let i = 0; i < uv.count; i++) uv.setXY(i, uv.getX(i) ? bu1 : bu0, uv.getY(i) ? bv1 : bv0);
          boards.push(f.applyMatrix4(m4));
        }
      }
      if (k % 12 === 11) yield;
    }
    const tex = new THREE.CanvasTexture(sheet);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.anisotropy = 4;
    letGoOnceSent(tex);
    const sheetMat = new THREE.MeshLambertMaterial({ map: tex, polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -2 });
    const btex = new THREE.CanvasTexture(bsheet);
    btex.colorSpace = THREE.SRGBColorSpace;
    btex.anisotropy = 4;
    letGoOnceSent(btex);
    const boardMat = new THREE.MeshLambertMaterial({ map: btex, polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -2 });
    for (const [list, mat] of [[faces, sheetMat], [boards, boardMat], [darks, dark], [wins, shopWin]] as const) {
      if (!list.length) continue;
      const merged = mergeGeometries(list.map((geo) => (geo.index ? geo.toNonIndexed() : geo)));
      if (!merged) continue;
      const mesh = new THREE.Mesh(merged, mat);
      mesh.castShadow = true;
      scene.add(mesh);
      culler.add(mesh, 160);
    }
    yield;
  }
}
